  function productInfo() {
    var info = {}, issues = [], product = window.webapis && webapis.productinfo;
    try {
      if (product && product.getModel) info.model = String(product.getModel());
      else if (product && product.getModelCode) info.model = String(product.getModelCode());
      else issues.push('model API unavailable');
    } catch (e) { issues.push('model ' + e.name); }
    try {
      if (product && product.getFirmware) info.firmware = String(product.getFirmware());
      else issues.push('firmware API unavailable');
    } catch (e) { issues.push('firmware ' + e.name); }
    var platform = navigator.userAgent.match(/Tizen[\/ ]([0-9.]+)/i);
    if (platform) info.tizen = platform[1];
    if (issues.length) info.error = issues.join('; ');
    return info;
  }
