    fresh.id = 'html-player'; fresh.width = 1920; fresh.height = 1080;
    fresh.preload = 'auto'; fresh.setAttribute('playsinline', '');
    fresh.style.background = 'black'; fresh.muted = false; fresh.volume = 1;
    document.body.classList.add('html-playing');
    document.documentElement.classList.add('html-playing');
